const $=id=>document.getElementById(id);
let lang='en',view='research',filter='all',selectedId='DEMO-06',realSamples=[],demoSamples=[],reviews=[],audioUrls=[],recordStatusKey='recordIdle',busy=false,recorder,stream,audioCtx,source,analyser,animation,timer,started,chunks=[],settings={},reviewStorageOk=true;
