function makeDemo(){const specs=[['DEMO-01','2026-10-09T09:00:00+03:00','referenceName','reference',180,.16,1],['DEMO-02','2026-10-10T09:00:00+03:00','repeatName','stable',180,.158,2],['DEMO-03','2026-10-11T09:00:00+03:00','repeatName','stable',180,.163,3],['DEMO-04','2026-10-12T09:00:00+03:00','poorName','poor',180,.002,4],['DEMO-05','2026-10-13T09:00:00+03:00','repeatName','stable',180,.159,5],['DEMO-06','2026-10-14T09:00:00+03:00','changedName','changed',340,.205,6]];demoSamples=specs.map(([id,date,nameKey,status,freq,amp,seed])=>{const pcm=Signal.synth({freq,amp,seed});return{id,date,kind:'synthetic',nameKey,status,device:'SYNTH-01',condition:'synthetic',note:'',blob:Signal.wav(pcm,16000),metrics:Signal.analyze([pcm],16000)};});}
