function canvasSetup(canvas,width=900,height=250){canvas.width=width;canvas.height=height;return canvas.getContext('2d');}
function drawTrend(){const c=$('trendChart'),ctx=canvasSetup(c,900,250),left=65,right=850,top=20,bottom=205,min=-70,max=-10;ctx.font='14px Arial';ctx.textAlign='right';ctx.fillStyle='#8b9d94';ctx.strokeStyle='#edf1ed';ctx.lineWidth=1;for(let v=min;v<=max;v+=20){const y=bottom-(v-min)/(max-min)*(bottom-top);ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.fillText(v+' dBFS',left-10,y+4);}const points=demoSamples.map((s,i)=>[left+i*(right-left)/(demoSamples.length-1),bottom-(Math.max(min,s.metrics.rmsDb??min)-min)/(max-min)*(bottom-top)]);const gradient=ctx.createLinearGradient(0,top,0,bottom);gradient.addColorStop(0,'#74b09540');gradient.addColorStop(1,'#74b09502');ctx.beginPath();ctx.moveTo(points[0][0],bottom);points.forEach(p=>ctx.lineTo(...p));ctx.lineTo(right,bottom);ctx.closePath();ctx.fillStyle=gradient;ctx.fill();ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle='#368b70';ctx.lineWidth=3;ctx.stroke();points.forEach(([x,y],i)=>{ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fillStyle=i===5?'#df936d':'#368b70';ctx.fill();ctx.textAlign='center';ctx.fillStyle='#8b9d94';ctx.fillText(new Date(demoSamples[i].date).toLocaleDateString(locale(),{day:'2-digit',month:'short'}),x,234);});}
function drawWave(canvas,metrics){const ctx=canvasSetup(canvas,1000,200);ctx.strokeStyle='#dce8df';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,100);ctx.lineTo(1000,100);ctx.stroke();ctx.strokeStyle='#3f9477';ctx.lineWidth=1.5;const w=metrics.waveform||[];w.forEach(([min,max],i)=>{const x=i/Math.max(1,w.length-1)*1000;ctx.beginPath();ctx.moveTo(x,100-max*92);ctx.lineTo(x,100-min*92);ctx.stroke();});}
function drawSpectrum(canvas,m){const ctx=canvasSetup(canvas,1000,190),limit=Math.min(2000,m.sampleRate/2),maxBin=Math.floor(limit/m.binHz),spec=m.spectrum;const peak=Math.max(...spec.slice(1,maxBin+1),1e-20);ctx.strokeStyle='#719e87';ctx.lineWidth=2;ctx.beginPath();for(let k=1;k<=maxBin;k++){const db=10*Math.log10(Math.max(spec[k],1e-20)/peak),x=k/maxBin*1000,y=170-Math.max(0,(db+70)/70)*150;k===1?ctx.moveTo(x,y):ctx.lineTo(x,y);}ctx.stroke();ctx.font='14px Arial';ctx.fillStyle='#91a295';ctx.textAlign='center';[0,500,1000,1500,2000].filter(h=>h<=limit).forEach(h=>ctx.fillText(h+' Hz',Math.max(25,Math.min(970,h/limit*1000)),188));}
function revokeAudio(){audioUrls.forEach(u=>URL.revokeObjectURL(u));audioUrls=[];}
function renderLibrary(){document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));const list=samples().filter(s=>filter==='all'||s.kind===filter).sort((a,b)=>new Date(b.date)-new Date(a.date));$('libraryCount').textContent=list.length;$('recordingList').replaceChildren();if(!list.some(s=>s.id===selectedId))selectedId=list[0]?.id||null;list.forEach(s=>{const b=el('button','sample-row'+(s.id===selectedId?' selected':''));b.append(el('span','sample-icon','≋'));const info=el('div');info.append(el('strong',null,sampleName(s)),el('p',null,dateLabel(s.date)+' · '+fmt(s.metrics.duration,1)+' s · '+(s.kind==='synthetic'?t('synthetic'):t('real'))));b.append(info,el('span','sample-status'+(['changed','poor'].includes(s.status)?' warn':''),statusName(s)));b.onclick=()=>{selectedId=s.id;renderLibrary();};$('recordingList').append(b);});if(!list.length)$('recordingList').append(el('div','empty',t('listEmpty')));renderDetail(samples().find(s=>s.id===selectedId));}
function renderDetail(s){revokeAudio();const root=$('sampleDetail');root.replaceChildren();if(!s){root.append(el('div','empty',t('listEmpty')));return;}const m=s.metrics,top=el('div','detail-top');top.append(el('h2',null,sampleName(s)),el('span','badge'+(s.kind==='real'?' teal':''),t(s.kind==='synthetic'?'synthetic':'real')));root.append(top,el('div','detail-meta',dateLabel(s.date)+' · '+s.id+' · '+(s.kind==='synthetic'?t('demoCondition'):t(s.condition==='position'?'differentPosition':s.condition))));const waveBox=el('div','audio-chart'),labels=el('div','chart-label');labels.append(el('span',null,t('pcmLabel')),el('span',null,fmt(m.duration,2)+' s'));const wave=el('canvas');wave.setAttribute('aria-label',lang==='en'?'Full recording waveform':'الموجة الصوتية للتسجيل كاملًا');waveBox.append(labels,wave);root.append(waveBox);drawWave(wave,m);const audio=el('audio');audio.controls=true;const url=URL.createObjectURL(s.blob);audioUrls.push(url);audio.src=url;root.append(audio,el('div','inline-note',t(s.kind==='synthetic'?'syntheticNote':'realNote')));const grid=el('div','measurement-grid');[['duration',fmt(m.duration,2),'s'],['rms',level(m.rmsDb),'dBFS'],['peak',level(m.peakDb),'dBFS'],['nearLimit',fmt(m.nearLimitPct,3),'%'],['dominant',fmt(m.dominantHz,1),'Hz'],['centroid',fmt(m.centroidHz,1),'Hz']].forEach(([key,value,unit])=>{const box=el('div','measurement');box.append(el('span',null,t(key)),el('strong',null,value),el('small',null,unit));grid.append(box);});root.append(grid);const specBox=el('div','audio-chart');specBox.append(el('div','chart-label',t('powerLabel')));const spec=el('canvas');spec.setAttribute('aria-label',lang==='en'?'Relative audio power spectrum':'طيف القدرة الصوتية النسبي');specBox.append(spec);root.append(specBox);drawSpectrum(spec,m);root.append(el('p','detail-meta',t('sampleRate')+': '+m.sampleRate+' Hz · '+t('resolution')+': '+fmt(m.binHz,2)+' Hz · '+t('channels')+': '+m.channels));const label=el('label',null,t('referenceSelect')),select=el('select');select.setAttribute('aria-label',t('referenceSelect'));const available=samples().filter(r=>r.id!==s.id&&r.kind===s.kind&&r.metrics.sampleRate===m.sampleRate);const first=el('option',null,t('noComparison'));first.value='';select.append(first);available.forEach(r=>{const opt=el('option',null,sampleName(r)+' · '+dateLabel(r.date));opt.value=r.id;select.append(opt);});const comparison=el('div','status-message');select.onchange=()=>{const r=samples().find(x=>x.id===select.value);const similarity=r?Signal.similarity(m,r.metrics):null;comparison.textContent=r?t('similarity')+': '+fmt(similarity,4)+' / 1.0000 · '+t('similarityNote'):t('noComparison');};root.append(label,select,comparison);const reference=available.find(r=>r.id==='DEMO-01')||available.at(-1);if(reference){select.value=reference.id;select.onchange();}const q=m.rmsDb!==null&&m.rmsDb>-60?(m.nearLimitPct>0?'digitalNearLimit':'noFlag'):'digitalSilence';root.append(el('p','method-note',t('technicalQuality')+': '+t(q)+'. '+t('qualityExplanation')));if(s.settings){const keys=['echoCancellation','noiseSuppression','autoGainControl'];const text=keys.map(k=>k+': '+(typeof s.settings[k]==='boolean'?t(s.settings[k]?'on':'off'):t('unknown'))).join(' · ');root.append(el('p','method-note',t('micSettings')+': '+text));}if(s.note)root.append(el('p','detail-meta',s.note));const actions=el('div','detail-actions');const download=el('button','secondary',t('downloadAudio'));download.onclick=()=>downloadBlob(s.blob,s.id+extension(s.blob));actions.append(download);if(s.kind==='synthetic'&&['changed','poor'].includes(s.status)){const btn=el('button','primary',t('sendReview'));btn.onclick=()=>addReview(s);actions.append(btn);}if(s.kind==='real'){const btn=el('button','danger-link',t('deleteSample'));btn.onclick=()=>deleteSample(s.id);actions.append(btn);}root.append(actions,el('p','method-note',t('methodNote')));}
function addReview(s){if(reviews.some(r=>r.sampleId===s.id&&!r.done)){toast('alreadyQueued');show('care');return;}reviews.unshift({id:'REVIEW-'+Date.now(),sampleId:s.id,done:false,note:'',context:s.status==='poor'?'initialReviewB':'initialReviewA'});saveReviews();renderStats();show('care');toast('added');}
