$('resetDemo').onclick=()=>{if(confirm(t('resetConfirm'))){reviews=initialReviews();saveReviews();renderStats();renderReviews();toast('resetDone');}};
let db;const dbReady=new Promise((resolve,reject)=>{try{const req=indexedDB.open('fistulavoice-lab-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('samples',{keyPath:'id'});req.onsuccess=()=>{db=req.result;resolve();};req.onerror=()=>reject(req.error);}catch(e){reject(e);}});dbReady.catch(()=>{});
async function dbAction(mode,fn){await dbReady;return new Promise((resolve,reject)=>{const tx=db.transaction('samples',mode),req=fn(tx.objectStore('samples'));let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function decodeBlob(blob){const context=new (window.AudioContext||window.webkitAudioContext)();try{const buffer=await context.decodeAudioData(await blob.arrayBuffer());const channels=Array.from({length:buffer.numberOfChannels},(_,i)=>buffer.getChannelData(i));return Signal.analyze(channels,buffer.sampleRate);}finally{await context.close();}}
async function loadReal(){const items=await dbAction('readonly',s=>s.getAll());realSamples=[];for(const item of items){if(!item.blob)continue;let metrics=item.metrics;if(!metrics||metrics.method!=='pcm-hann-fft-v2'){try{metrics=await decodeBlob(item.blob);}catch{continue;}}realSamples.push({...item,id:String(item.id),date:item.date||new Date(Number(item.id)).toISOString(),kind:'real',condition:item.conditionKey||(['quiet','repeat','noise','position'].includes(item.condition)?item.condition:'quiet'),metrics});}realSamples.sort((a,b)=>new Date(b.date)-new Date(a.date));renderStats();renderVisible();}
function renderLab(){$('labSamples').replaceChildren();realSamples.forEach(s=>{const row=el('div','capture-item'),info=el('div');info.append(el('strong',null,sampleName(s)),el('p',null,dateLabel(s.date)+' · '+fmt(s.metrics.duration,2)+' s · RMS '+level(s.metrics.rmsDb)+' dBFS'));const b=el('button','secondary',t('viewSample'));b.onclick=()=>{selectedId=s.id;filter='real';show('recordings');};row.append(info,b);$('labSamples').append(row);});if(!realSamples.length)$('labSamples').append(el('div','empty',t('labEmpty')));}
function extension(blob){return blob.type.includes('wav')?'.wav':blob.type.includes('mp4')?'.m4a':'.webm';}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportCsv(onlyReal=false){const list=onlyReal?realSamples:samples();if(!list.length){toast('noneExport');return;}const fields=['id','source','date_iso','device_code','conditions','note','duration_s','rms_linear','rms_dbfs','peak_linear','peak_dbfs','near_limit_pct','dominant_hz','centroid_hz','decoded_sample_rate_hz','channels','fft_size','fft_bin_hz','fft_frames','echo_cancellation','noise_suppression','auto_gain_control'];const rows=list.map(s=>{const m=s.metrics;return[s.id,s.kind,s.date,s.device,s.kind==='synthetic'?'generated signal':s.condition,s.note,m.duration,m.rms,m.rmsDb??'-Infinity',m.peak,m.peakDb??'-Infinity',m.nearLimitPct,m.dominantHz,m.centroidHz,m.sampleRate,m.channels,m.fftSize,m.binHz,m.frames,s.settings?.echoCancellation??'',s.settings?.noiseSuppression??'',s.settings?.autoGainControl??''];});const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const csv=[fields,...rows].map(row=>row.map(cell).join(',')).join('\r\n');downloadBlob(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}),'fistulavoice-'+(onlyReal?'captures':'all-measurements')+'.csv');toast('copied');}
$('exportAll').onclick=()=>exportCsv();$('exportLab').onclick=()=>exportCsv(true);
async function deleteSample(id){if(busy){toast('stopFirst');return;}if(!confirm(t('deleteOneConfirm')))return;const s=realSamples.find(s=>s.id===id);if(!s)return;const originalId=/^\d+$/.test(id)?Number(id):id;try{await dbAction('readwrite',store=>store.delete(originalId));await loadReal();toast('deleted');}catch{toast('operationError');}}
$('deleteAll').onclick=async()=>{if(busy){toast('stopFirst');return;}if(confirm(t('deleteConfirm'))){try{await dbAction('readwrite',s=>s.clear());await loadReal();toast('allDeleted');}catch{toast('operationError');}}};
function cleanup(){cancelAnimationFrame(animation);clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());source?.disconnect();audioCtx?.close().catch(()=>{});stream=null;source=null;busy=false;$('record').disabled=false;$('stop').disabled=true;$('liveLabel').textContent=t('ready');}
function monitor(){if(!busy||recorder?.state!=='recording')return;const data=new Float32Array(analyser.fftSize);analyser.getFloatTimeDomainData(data);const c=$('liveWave'),ctx=canvasSetup(c,900,200);ctx.strokeStyle='#8fcbb5';ctx.lineWidth=2;ctx.beginPath();let square=0;for(let i=0;i<data.length;i++){square+=data[i]**2;const x=i/data.length*900,y=100-data[i]*85;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();const seconds=Math.min(15,(performance.now()-started)/1000);$('elapsed').textContent='00:'+Math.floor(seconds).toString().padStart(2,'0')+' / 00:15';$('liveLabel').textContent=t('recordingNow');$('recordStatus').textContent=t('liveRms')+': '+level(square>0?20*Math.log10(Math.sqrt(square/data.length)):null)+' dBFS';animation=requestAnimationFrame(monitor);}
$('record').onclick=async()=>{if(busy)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){setStatus('micUnsupported',true);return;}busy=true;$('record').disabled=true;setStatus('permission');try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});settings=stream.getAudioTracks()[0].getSettings();audioCtx=new (window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();source=audioCtx.createMediaStreamSource(stream);analyser=audioCtx.createAnalyser();analyser.fftSize=2048;source.connect(analyser);const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(type=>MediaRecorder.isTypeSupported(type));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);chunks=[];const meta={device:$('device').value.trim(),conditionKey:$('condition').value,note:$('sampleNote').value.trim(),settings:{echoCancellation:settings.echoCancellation,noiseSuppression:settings.noiseSuppression,autoGainControl:settings.autoGainControl,sampleRate:settings.sampleRate,channelCount:settings.channelCount}};let failed=false;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=()=>{failed=true;cleanup();setStatus('recordError',true);};recorder.onstop=async()=>{const blob=new Blob(chunks,{type:recorder.mimeType}),wallDuration=(performance.now()-started)/1000;cleanup();if(failed)return;if(!blob.size||wallDuration<1){setStatus('tooShort',true);return;}busy=true;$('record').disabled=true;setStatus('processing');let metrics;try{metrics=await decodeBlob(blob);}catch{busy=false;$('record').disabled=false;downloadBlob(blob,'fistulavoice-raw-'+Date.now()+extension(blob));setStatus('decodeError',true);return;}const sample={id:'CAP-'+Date.now(),date:new Date().toISOString(),kind:'real',...meta,condition:meta.conditionKey,blob,metrics};try{await dbAction('readwrite',s=>s.put(sample));await loadReal();setStatus(metrics.rmsDb===null||metrics.rmsDb<-60?'lowSaved':'saved',metrics.rmsDb===null||metrics.rmsDb<-60);}catch{downloadBlob(blob,sample.id+extension(blob));setStatus('storageError',true);}finally{busy=false;$('record').disabled=false;}};started=performance.now();recorder.start();$('stop').disabled=false;monitor();timer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop();},15000);}catch(e){cleanup();setStatus(e.name==='NotAllowedError'?'micDenied':'recordError',true);}};
